@GetMapping("Expression_Arithmetic_001_T/{cmd}")
  public Map<String, Object> expression_arithmetic_001_t(@PathVariable int cmd) {
    Map<String, Object> modelMap = new HashMap<>();
    try {
      // 场景特点：加法运算保持污点传播
      int result = cmd + 100;
      Runtime.getRuntime().exec(String.valueOf(result));
      modelMap.put("status", "success");
    } catch (Exception e) {
      modelMap.put("status", "error");
    }
    return modelMap;
  }
